def solution(feeds, limit):
    # Flatten everything and sort: O(N log N) over all N posts.
    posts = []
    for feed in feeds:
        for ts, post_id in feed:
            posts.append((-ts, post_id))
    posts.sort()
    return [post_id for _, post_id in posts[:limit]]
